class.description:
Extend this resource in a script, implement [method _get_glyph], save it, and set [member ProjectSettings.input_devices/router/glyph_provider] to its path. [method InputRouter.get_input_glyph] loads it on first use and forwards every request to it.
[codeblock]
extends GamepadGlyphProvider

@export var atlases: Dictionary[int, Texture2D] # One atlas per pad family.

func _get_glyph(family, input):
	var atlas = AtlasTexture.new()
	atlas.atlas = atlases.get(family, atlases[InputRouter.PAD_FAMILY_GENERIC])
	atlas.region = Rect2(input * 64, 0, 64, 64)
	return atlas
[/codeblock]
